package library.flow; public class BipartiteMatching {public int maxMatching(boolean[][] a){int n=a.length,m=a[0].length;int[] mt=new int[m];for(int j=0;j<m;j++)mt[j]=-1;int ans=0;for(int i=0;i<n;i++){boolean[] seen=new boolean[m];if(dfs(i,a,mt,seen))ans++;}return ans;}private boolean dfs(int u,boolean[][]a,int[]mt,boolean[]s){for(int v=0;v<a[u].length;v++)if(a[u][v]&&!s[v]){s[v]=true;if(mt[v]<0||dfs(mt[v],a,mt,s)){mt[v]=u;return true;}}return false;}}
